CREATE TABLE IF NOT EXISTS economic_trusted_signal_aggregates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, signal_count integer NOT NULL DEFAULT 0, average_signal_score numeric(5,2) NOT NULL DEFAULT 0, weighted_score numeric(5,2) NOT NULL DEFAULT 0, confidence text NOT NULL DEFAULT 'low', signal_types jsonb NOT NULL DEFAULT '[]'::jsonb, source_ids jsonb NOT NULL DEFAULT '[]'::jsonb, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_trusted_signal_aggregates_profile ON economic_trusted_signal_aggregates(profile_id,created_at DESC);